CREATE TABLE IF NOT EXISTS roles(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS permissions(id INTEGER PRIMARY KEY, key TEXT NOT NULL UNIQUE, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role_id INTEGER NOT NULL REFERENCES roles(id), permission_id INTEGER NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS departments(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, code TEXT NOT NULL UNIQUE, archived_at TEXT);
CREATE TABLE IF NOT EXISTS locations(id INTEGER PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, address TEXT, timezone TEXT NOT NULL DEFAULT 'Europe/Berlin', department_id INTEGER REFERENCES departments(id), archived_at TEXT);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, external_subject TEXT UNIQUE, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deactivated','archived')), department_id INTEGER REFERENCES departments(id), default_location_id INTEGER REFERENCES locations(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_roles(user_id INTEGER NOT NULL REFERENCES users(id), role_id INTEGER NOT NULL REFERENCES roles(id), assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, assigned_by INTEGER REFERENCES users(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS resource_types(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, code TEXT NOT NULL UNIQUE, description TEXT NOT NULL, is_bookable INTEGER NOT NULL DEFAULT 1, archived_at TEXT);
CREATE TABLE IF NOT EXISTS resources(id INTEGER PRIMARY KEY, resource_type_id INTEGER NOT NULL REFERENCES resource_types(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', manufacturer TEXT, model TEXT, serial_number TEXT UNIQUE, asset_number TEXT UNIQUE, home_location_id INTEGER REFERENCES locations(id), current_location_id INTEGER REFERENCES locations(id), responsible_department_id INTEGER REFERENCES departments(id), responsible_manager_id INTEGER REFERENCES users(id), status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','reserved','checked_out','under_maintenance','damaged','lost','unavailable','archived')), is_bookable INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by INTEGER REFERENCES users(id), updated_by INTEGER REFERENCES users(id), archived_at TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY, occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, actor_user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, request_id TEXT NOT NULL, ip_address_hash TEXT, before_data TEXT, after_data TEXT, reason TEXT);
